def closest_pair_sum(nums, target):
    """返回和最接近target的两个下标。"""
    pairs = sorted((v, i) for i, v in enumerate(nums))
    lo, hi = 0, len(pairs) - 1
    best = None
    while lo < hi:
        s = pairs[lo][0] + pairs[hi][0]
        if best is None or abs(s - target) < abs(best[0] - target):
            best = (s, pairs[lo][1], pairs[hi][1])
        if s < target:
            lo += 1
        elif s > target:
            hi -= 1
        else:
            break
    i, j = best[1], best[2]
    return [min(i, j), max(i, j)]
```

